export type Currency = "USD" | "EUR" | "GBP";

const SYMBOL: Record<Currency, string> = { USD: "$", EUR: "€", GBP: "£" };

/** Parses "1234", "1234.5" or "-1234.50" into integer cents. Throws on anything else. */
export function toCents(text: string): number {
  const m = /^(-)?(\d+)(?:\.(\d{1,2}))?$/.exec(text.trim());
  if (!m) throw new Error(`not an amount: ${text}`);
  const cents = Number(m[2]) * 100 + Number((m[3] ?? "0").padEnd(2, "0"));
  return m[1] ? -cents : cents;
}

/** An amount for people: "$1234.50", and "-$12.00" for a negative one. */
export function formatMoney(cents: number, currency: Currency = "USD"): string {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const whole = Math.floor(abs / 100);
  const frac = String(abs % 100).padStart(2, "0");
  return `${sign}${SYMBOL[currency]}${whole}.${frac}`;
}

/** A percentage of an amount, rounded half up to the cent. */
export function percentOf(cents: number, percent: number): number {
  return Math.round((cents * percent) / 100);
}
import { dueDate } from "./clock.ts";
import { type Invoice, total } from "./invoice.ts";
import { formatMoney } from "./money.ts";

const HEADER = "number,customer,due,total";

function field(text: string): string {
  return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

/** The accounting export, RFC 4180 CSV: one row per invoice. */
export function toCsv(invoices: Invoice[]): string {
  const rows = invoices.map((invoice) =>
    [
      invoice.number,
      field(invoice.customer),
      dueDate(invoice.issued, invoice.termsDays),
      formatMoney(total(invoice), invoice.currency),
    ].join(","),
  );
  return [HEADER, ...rows].join("\n");
}
import { dueDate } from "./clock.ts";
import { type Invoice, total } from "./invoice.ts";
import { formatMoney } from "./money.ts";

/** The monthly summary finance pastes into its newsletter: one line per invoice, then the total. */
export function monthlySummary(invoices: Invoice[], month: string): string {
  const inMonth = invoices.filter((invoice) => invoice.issued.startsWith(month));
  const lines = inMonth.map(
    (invoice) =>
      `${invoice.number}  ${invoice.customer.padEnd(14)}  due ${dueDate(invoice.issued, invoice.termsDays)}  ${formatMoney(total(invoice), invoice.currency)}`,
  );
  const sum = inMonth.reduce((acc, invoice) => acc + total(invoice), 0);
  return [`Invoices issued in ${month}: ${inMonth.length}`, ...lines, `Total: ${formatMoney(sum)}`].join("\n");
}
import { dueDate } from "./clock.ts";
import { type Currency, percentOf } from "./money.ts";

export interface Line {
  description: string;
  quantity: number;
  unitCents: number;
}

export interface Invoice {
  number: string;
  customer: string;
  currency: Currency;
  issued: string;
  termsDays: number;
  lines: Line[];
  discountPercent?: number;
  taxPercent: number;
}

export function subtotal(invoice: Invoice): number {
  return invoice.lines.reduce((sum, line) => sum + line.quantity * line.unitCents, 0);
}

export function discount(invoice: Invoice): number {
  return percentOf(subtotal(invoice), invoice.discountPercent ?? 0);
}

export function tax(invoice: Invoice): number {
  return percentOf(subtotal(invoice) - discount(invoice), invoice.taxPercent);
}

export function total(invoice: Invoice): number {
  return subtotal(invoice) - discount(invoice) + tax(invoice);
}

/** The invoice as the billing API exchanges it (see test/contract/). */
export function toJSON(invoice: Invoice) {
  return {
    number: invoice.number,
    customer: invoice.customer,
    currency: invoice.currency,
    issued: invoice.issued,
    due: dueDate(invoice.issued, invoice.termsDays),
    subtotal: subtotal(invoice),
    discount: discount(invoice),
    tax: tax(invoice),
    total: total(invoice),
  };
}
